INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Serupa tapi Sering Salah Paham$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak orang Indonesia merasa sudah bisa bahasa Melayu karena mirip bahasa Indonesia. Padahal, banyak kata yang sama bunyinya tetapi berbeda artinya — salah memakai bisa menimbulkan salah paham bahkan menyinggung lawan bicara di Malaysia, Singapura, atau Brunei.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Satu Akar, Dua Perkembangan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Bahasa Indonesia dan bahasa Melayu baku sama-sama berakar dari bahasa Melayu. Namun sejak abad ke-20 keduanya berkembang terpisah: Indonesia menyerap banyak kata dari bahasa daerah dan Belanda, sedangkan Melayu baku Malaysia menyerap dari bahasa Inggris. Hasilnya, kosakata sehari-hari banyak yang berbeda.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Kamus Melayu–Indonesia (aplikasi atau cetak)$txt$, $txt$Aplikasi penerjemah untuk verifikasi$txt$, $txt$Catatan kecil untuk mencatat kata jebakan$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Kuasai Kata Jebakan dan Istilah yang Berbeda$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Pertama, hafalkan kata jebakan (false friends): "percuma" dalam bahasa Melayu berarti gratis, bukan sia-sia; "kereta" berarti mobil, bukan kereta api. Kedua, kenali istilah yang berbeda total per kategori — transportasi, makanan, pekerjaan — misalnya "pejabat" (Melayu: pegawai biasa) dan "hospital" (Malaysia) vs "rumah sakit" (Indonesia). Mulai dari 20 kata paling sering dipakai, perluas hingga 100 kata dalam 30 hari.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Risiko terbesar adalah menganggap semua kata sama. Jangan menebak arti dari konteks penting seperti kontrak, petunjuk medis, atau aturan hukum — selalu verifikasi dengan kamus. Hindari juga memakai slang Indonesia yang tidak dikenal di Malaysia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Uji pemahaman Anda: tonton berita TV Malaysia 10 menit dan catat kata yang berbeda maknanya. Jika Anda bisa mengidentifikasi 8 dari 10 kata jebakan umum tanpa kamus, pemahaman dasar Anda sudah cukup. Lanjutkan dengan berlatih percakapan langsung dan membaca portal berita Malaysia secara rutin.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Tiba-tiba Berkeringat Dingin$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Keringat dingin — tubuh berkeringat padahal tidak panas dan kulit terasa dingin — sering membuat panik. Kondisi ini bisa disebabkan hal ringan seperti cemas, tetapi kadang menjadi tanda kondisi serius yang butuh penanganan cepat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Mengapa Tubuh Mengeluarkan Keringat Dingin$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Keringat dingin terjadi saat sistem saraf memicu respons "lawan atau lari": pembuluh darah menyempit dan kelenjar keringat aktif. Pemicu umum meliputi kecemasan, nyeri hebat, gula darah rendah, mual, dan infeksi. Pada kasus serius, bisa menyertai serangan jantung atau syok.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan: Yang Perlu Disiapkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Air putih atau oralit$txt$, $txt$Tempat duduk/berbaring yang aman$txt$, $txt$Makanan/minuman manis bila curiga gula darah rendah$txt$, $txt$Nomor darurat 119 tersimpan di HP$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Pertolongan di Rumah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Duduk atau berbaringlah agar tidak jatuh pingsan. Minum air putih sedikit demi sedikit. Jika belum makan lama, makan atau minum yang manis. Longgarkan pakaian, bernapas perlahan, dan istirahat 15–30 menit sambil memantau kondisi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko: Tanda Bahaya Wajib ke Dokter/IGD$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Segera cari pertolongan medis bila keringat dingin disertai nyeri dada, sesak napas, pingsan, muntah hebat, demam tinggi, atau tidak membaik setelah istirahat. Jangan menunda bila ada riwayat penyakit jantung, diabetes, atau tekanan darah tinggi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Catatan Penting$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Catat kapan keringat dingin muncul, berapa lama, dan apa yang menyertainya — pola yang berulang membantu dokter menegakkan diagnosis. Artikel ini bersifat informasi umum dan bukan pengganti nasihat medis; bila sering kambuh atau disertai gejala mengkhawatirkan, konsultasikan ke dokter.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Delta dan Bagaimana Terbentuk?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Delta adalah daratan berbentuk kipas di muara sungai, terbentuk dari endapan lumpur, pasir, dan kerikil yang dibawa sungai selama ribuan tahun. Delta terbentuk ketika aliran sungai melambat di muara sehingga tidak mampu lagi membawa sedimen; endapan menumpuk, sungai bercabang, dan daratan baru tumbuh perlahan — proses yang masih berlangsung hingga kini.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Delta Terbesar: Gangga-Brahmaputra$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Delta Gangga-Brahmaputra di Bangladesh dan India adalah delta terbesar di dunia, membentang sekitar 100.000 kilometer persegi. Delta ini menopang lebih dari 100 juta manusia dan menjadi rumah hutan bakau Sundarbans, habitat harimau Benggala.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Delta Raksasa Lainnya di Dunia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Delta Mekong di Vietnam terkenal sebagai lumbung beras Asia Tenggara; delta Nil di Mesir menjadi pusat peradaban sejak zaman firaun. Di Indonesia, delta Mahakam di Kalimantan Timur dan delta Kapuas menjadi kawasan penting perikanan dan hutan bakau.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Manfaat Delta bagi Manusia dan Peradaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Tanah delta yang subur ideal untuk pertanian dan tambak; muaranya yang tenang menjadi pelabuhan alami; hutan bakaunya melindungi pantai dari abrasi. Hampir semua peradaban besar lahir di delta atau dataran banjir sungai — kesuburan delta memungkinkan surplus pangan, fondasi kota dan negara.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Ancaman terhadap Delta dan Cara Menjaganya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Banyak delta terancam penurunan muka tanah, berkurangnya sedimen karena bendungan di hulu, dan kenaikan muka air laut. Melindungi delta berarti mengelola seluruh daerah aliran sungai: menjaga hutan di hulu dan menahan laju penurunan tanah. Delta yang sehat adalah benteng alami menghadapi perubahan iklim.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Nanoteknologi dan Mengapa Istimewa?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Nanoteknologi adalah ilmu memanipulasi materi pada skala nanometer — sepermiliar meter; sehelai rambut manusia kira-kira 80.000 nanometer lebarnya. Pada skala ini rasio luas permukaan terhadap volume menjadi sangat besar sehingga sifat materi berubah drastis: emas yang inert bisa menjadi katalis sangat aktif dalam bentuk nanopartikel.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penerapan dalam Kedokteran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Nanopartikel digunakan untuk mengantar obat langsung ke sel kanker tanpa merusak sel sehat, mempercepat penyembuhan luka, dan membuat alat diagnosis yang bisa mendeteksi penyakit dari setetes darah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Penerapan dalam Elektronik, Energi, dan Sehari-hari$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Chip komputer modern memakai transistor berukuran beberapa nanometer; panel surya berlapis nano menyerap cahaya lebih efisien. Tanpa disadari kita sudah memakainya: tabir surya nanopartikel, kain anti-noda, dan layar HP tahan gores berlapis nano.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Tantangan dan Keamanan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Partikel nano yang sangat kecil berpotensi menembus sel tubuh dan lingkungan dengan cara yang belum sepenuhnya dipahami. Para ilmuwan mengembangkan aturan keamanan nano agar manfaatnya bisa dinikmati tanpa risiko kesehatan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Masa Depan dan Peran Indonesia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Riset masa depan mengarah ke robot nano untuk operasi dari dalam tubuh dan material yang memperbaiki dirinya sendiri. Indonesia mengembangkan riset nano dari hasil alam: nanosilika dari sekam padi dan nanoenkapsulasi untuk obat herbal — mengubah limbah pertanian menjadi produk bernilai tinggi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) mengidentifikasi jenis-jenis gerak pada tumbuhan; (2) menjelaskan alat gerak pada hewan; (3) mendeskripsikan sistem gerak manusia (tulang, sendi, otot); (4) menyebutkan gangguan pada sistem gerak dan pencegahannya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Gerak pada Tumbuhan dan Hewan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Tumbuhan bergerak meski tidak berpindah tempat: tropisme (arah tumbuh mengikuti rangsang, misalnya ke arah cahaya), nasti (misalnya putri malu menutup daun saat disentuh), dan taksis (gerak pindah tempat). Hewan bergerak untuk mencari makan dan menghindari bahaya dengan alat gerak seperti kaki, sayap, sirip, dan otot perut.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Rangka Manusia: Tulang dan Sendi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Rangka manusia tersusun atas sekitar 206 tulang: tulang pipa (paha), pipih (tengkorak), pendek (pergelangan), dan tidak beraturan (tulang belakang). Sendi menghubungkan tulang: sendi mati (tengkorak), sendi kaku (tulang belakang), dan sendi gerak seperti sendi lutut, siku, dan bahu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Otot: Penggerak Aktif$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Otot berkontraksi menarik tulang. Ada otot lurik (melekat pada tulang, bekerja sadar), otot polos (di organ dalam, tak sadar), dan otot jantung (tak sadar, tidak cepat lelah). Otot bekerja berpasangan secara antagonis, misalnya bisep dan trisep.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Gangguan Sistem Gerak dan Contoh Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Gangguan umum: patah tulang (fraktura), terkilir, osteoporosis (kurang kalsium), artritis (radang sendi), dan kelainan tulang belakang (lordosis/kifosis/skoliosis). Contoh soal: "Jelaskan perbedaan tropisme dan nasti!" Jawab: tropisme arahnya dipengaruhi arah rangsang (akar ke arah gravitasi), nasti tidak (putri malu menutup saat disentuh).$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$1. Jelaskan perbedaan alat gerak aktif dan pasif! (Jawab: aktif = otot yang berkontraksi; pasif = tulang yang digerakkan otot)$txt$, $txt$2. Sebutkan tiga macam sendi gerak beserta contohnya! (Jawab: peluru/bahu, engsel/siku-lutut, putar/leher)$txt$, $txt$3. Mengapa bisep dan trisep disebut antagonis? (Jawab: bekerja berlawanan — saat bisep berkontraksi, trisep berelaksasi, dan sebaliknya)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar, kamu diharapkan bisa: (1) menyebutkan contoh keragaman di kelas dan lingkungan; (2) menceritakan asal daerah teman; (3) menunjukkan sikap menghargai perbedaan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Keragaman?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Keragaman artinya bermacam-macam atau berbeda-beda. Di kelasmu, teman-temanmu berbeda: ada yang rambutnya lurus ada yang keriting, ada yang suka menggambar ada yang suka bernyanyi. Perbedaan itu indah dan harus dihargai.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Keragaman Suku Bangsa dan Agama$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Indonesia punya banyak suku: Jawa, Sunda, Batak, Minang, Bugis, Dayak, Papua, dan lainnya — masing-masing dengan bahasa dan makanan khas. Indonesia juga punya enam agama yang diakui: Islam, Kristen Protestan, Katolik, Hindu, Buddha, dan Konghucu. Kita harus saling menghormati dan tidak mengejek perbedaan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Keragaman Kegemaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Setiap anak punya kesukaan berbeda: ada yang suka sepak bola, ada yang suka menari, ada yang suka membaca. Perbedaan kegemaran membuat pertemanan semakin seru karena kita bisa saling berbagi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Sikap Menghargai Perbedaan dalam Sehari-hari$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Cara menghargai perbedaan: tidak mengejek teman yang berbeda, mau bermain dengan siapa saja, dan mengucapkan selamat saat teman merayakan hari rayanya. Contohnya: saat ada teman yang puasa, kita tidak makan di depannya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Ayo Berlatih dan Kunci Jawaban$txt$));
